+    fn flock_for_whole_file(lock_type: libc::c_short) -> libc::flock {
+        let mut lock = unsafe { mem::zeroed::<libc::flock>() };
+        lock.l_type = lock_type;
+        lock.l_whence = libc::SEEK_SET as libc::c_short;
+        lock.l_start = 0;
+        lock.l_len = 0;
